#!/usr/bin/env bash
# TENNIS PAPER QUOTER — live maker measurement, $0 at risk.
set -e
cd /root/sports-bot-optimal
echo '' | base64 -d > paper_quoter.py
.venv/bin/python -m py_compile paper_quoter.py && echo "script verified"
tmux kill-session -t quoter 2>/dev/null || true
tmux new-session -d -s quoter "cd /root/sports-bot-optimal && .venv/bin/python paper_quoter.py; echo exited; read"
echo "PAPER QUOTER RUNNING in tmux session: quoter"
echo "Live status:   tail -F /root/sports-bot-optimal/quoter_progress.log"
echo "Fill records:  tail -F /root/sports-bot-optimal/paper_fills.csv"
sleep 15 && tail -3 /root/sports-bot-optimal/quoter_progress.log || true
